import http.server,json,os,pathlib,secrets,socket,subprocess,sys,tempfile,threading,urllib.request
assert sys.platform=='linux' and os.geteuid()!=0
print('NATIVE_LINUX_READY',flush=True)
token=secrets.token_hex(12);control={'mode':'ready'};seen=[]
class Handler(http.server.BaseHTTPRequestHandler):
 def do_GET(self):
  seen.append(self.path)
  if self.path=='/business':code=200;raw=b'business-available'
  elif control['mode']=='ready':code=200;raw=json.dumps({'status':'ready','instance':token}).encode()
  elif control['mode']=='wrong':code=200;raw=json.dumps({'status':'ready','instance':'wrong-instance'}).encode()
  elif control['mode']=='redirect':code=302;raw=b''
  elif control['mode']=='malformed':code=200;raw=b'not-json'
  elif control['mode']=='oversize':code=200;raw=b' '*5000
  else:code=503;raw=b'{"status":"not-ready"}'
  self.send_response(code)
  if code==302:self.send_header('Location','/business')
  self.send_header('Content-Length',str(len(raw)));self.end_headers()
  try:self.wfile.write(raw)
  except (BrokenPipeError,ConnectionResetError):pass
 def log_message(self,*args):pass
server=http.server.ThreadingHTTPServer(('127.0.0.1',0),Handler);thread=threading.Thread(target=server.serve_forever,daemon=True);thread.start()
